// One item per repository, so a repo that 404s costs that repo and not the run.
//
// Accepts what people actually paste: `owner/name`, a full GitHub URL, or the
// same with a trailing `.git`.
const cfg = $('Settings').first().json;
const raw = String(cfg.repos || '');

const seen = new Set();
const out = [];

for (const part of raw.split(/[,\n;]+/)) {
  const t = part
    .trim()
    .replace(/^https?:\/\/(www\.)?github\.com\//i, '')
    .replace(/\.git$/i, '')
    .replace(/\/+$/, '');
  if (!t) { continue; }
  const bits = t.split('/').filter(Boolean);
  if (bits.length < 2) {
    throw new Error('Settings.repos wants owner/name, got "' + part.trim() + '".');
  }
  const owner = bits[0];
  const repo = bits[1];
  const key = (owner + '/' + repo).toLowerCase();
  if (seen.has(key)) { continue; }
  seen.add(key);
  out.push({ json: { owner: owner, repo: repo, slug: owner + '/' + repo } });
}

if (!out.length) {
  throw new Error('No repositories in Settings. Put at least one owner/name in the repos field.');
}
return out;

// Both manifest branches land here, and which branch an item came from is read
// off the content rather than carried in a field: the GitHub node hands the
// input json straight through, so package.json and requirements.txt arrive
// looking identical. A JSON manifest starts with a brace, a pyproject has TOML
// section headers, and anything else is read as a requirements file.
//
// The version cleaning here is the reason this template exists. Measured on
// 2026-08-31: OSV answers `cookie@0.7.1` with zero advisories and
// `cookie@^0.7.1` with one, because it does not reject the range, it misreads
// it as the floor. So the floor is what gets sent - deliberately, and labelled -
// and every advisory is re-checked against its own fixed version later.
const cfg = $('Settings').first().json;
const cap = Math.max(10, Math.min(400, Number(cfg.max_packages) || 120));
const wantDev = String(cfg.include_dev || 'no').toLowerCase() === 'yes';

function cleanVersion(spec) {
  const s = String(spec === null || spec === undefined ? '' : spec).trim();
  // A git, file, workspace or npm-alias dependency has no version OSV can use.
  if (!s || s === '*' || s === 'latest' || /^(git|https?|file|link|workspace|npm|github):/i.test(s)) {
    return { version: '', pinned: false };
  }
  const m = s.match(/(\d+\.\d+(?:\.\d+)?(?:[-+][0-9A-Za-z.\-]+)?)/);
  if (!m) { return { version: '', pinned: false }; }
  // Pinned means the spec starts with the digit itself - no ^, ~, >=, or *.
  return { version: m[1], pinned: /^\d/.test(s) };
}

function addDep(map, ecosystem, name, spec, slug, dev) {
  const clean = String(name || '').trim();
  if (!clean) { return; }
  const key = ecosystem + '::' + clean.toLowerCase();
  const v = cleanVersion(spec);
  if (!map.has(key)) {
    map.set(key, {
      package_key: key,
      name: clean,
      ecosystem: ecosystem,
      osv_ecosystem: ecosystem === 'npm' ? 'npm' : 'PyPI',
      version: v.version,
      pinned: v.pinned,
      dev_only: dev,
      used_in: [],
      specs: [],
    });
  }
  const row = map.get(key);
  row.used_in.push(slug);
  row.specs.push(String(spec || 'unpinned'));
  // Several repos, several ranges: the oldest floor is the one that decides
  // whether an advisory can still bite, so that is the version asked about.
  if (v.version && (!row.version || compareVersions(v.version, row.version) < 0)) {
    row.version = v.version;
    row.pinned = v.pinned;
  }
  if (!dev) { row.dev_only = false; }
}

function compareVersions(a, b) {
  const pa = String(a).split(/[-+]/)[0].split('.');
  const pb = String(b).split(/[-+]/)[0].split('.');
  for (let i = 0; i < 3; i += 1) {
    const x = Number(pa[i] || 0);
    const y = Number(pb[i] || 0);
    if (x !== y) { return x < y ? -1 : 1; }
  }
  return 0;
}

const found = new Map();
let readable = 0;

for (const item of $input.all()) {
  const j = item.json || {};
  const text = String(j.data || '').trim();
  const slug = j.slug || ((j.owner || '?') + '/' + (j.repo || '?'));
  if (!text) { continue; }
  readable += 1;

  if (text.charAt(0) === '{') {
    let manifest = {};
    try { manifest = JSON.parse(text); } catch (e) { continue; }
    for (const block of ['dependencies', 'optionalDependencies']) {
      for (const [name, spec] of Object.entries(manifest[block] || {})) {
        addDep(found, 'npm', name, spec, slug, false);
      }
    }
    if (wantDev) {
      for (const [name, spec] of Object.entries(manifest.devDependencies || {})) {
        addDep(found, 'npm', name, spec, slug, true);
      }
    }
  } else if (/\[(project|build-system|tool\.poetry)\]/.test(text)) {
    // pyproject.toml. Worth handling rather than assuming requirements.txt:
    // checked on 2026-08-31, none of psf/requests, scrapy, transformers, rich,
    // localstack or airflow still has a requirements.txt at the repo root.
    //
    // Two shapes live in this file. PEP 621 puts an array of specifier strings
    // under [project]; Poetry puts `name = "^1.2"` lines under its own table.
    const pep = text.match(/^\s*dependencies\s*=\s*\[([\s\S]*?)\]/m);
    if (pep) {
      for (const q of pep[1].match(/"[^"]+"|'[^']+'/g) || []) {
        const spec = q.slice(1, -1);
        const m = spec.match(/^([A-Za-z0-9._-]+)\s*(?:\[[^\]]*\])?\s*(.*)$/);
        if (m) { addDep(found, 'pypi', m[1], (m[2] || '').replace(/[;,].*$/, ''), slug, false); }
      }
    }
    const poetry = text.split(/\[tool\.poetry\.dependencies\]/)[1];
    if (poetry) {
      for (const line of poetry.split(/\r?\n/)) {
        const l = line.split('#')[0].trim();
        if (!l) { continue; }
        if (l.charAt(0) === '[') { break; }
        const m = l.match(/^([A-Za-z0-9._-]+)\s*=\s*"?\{?\s*(?:version\s*=\s*")?([^",}]*)/);
        // python itself is a runtime constraint, not a package OSV knows.
        if (m && m[1].toLowerCase() !== 'python') {
          addDep(found, 'pypi', m[1], m[2] || '', slug, false);
        }
      }
    }
  } else {
    for (const line of text.split(/\r?\n/)) {
      const l = line.split('#')[0].trim();
      // -r, -e, --hash, bare URLs and editable installs are not packages.
      if (!l || l.charAt(0) === '-' || /^[a-z]+:\/\//i.test(l)) { continue; }
      const m = l.match(/^([A-Za-z0-9._-]+)\s*(?:\[[^\]]*\])?\s*(.*)$/);
      if (!m) { continue; }
      addDep(found, 'pypi', m[1], (m[2] || '').replace(/[;,].*$/, ''), slug, false);
    }
  }
}

if (!readable) {
  throw new Error('None of the repos returned a package.json or a ' + String(cfg.python_manifest || 'requirements.txt') + '. Check the repo names in Settings and that the GitHub credential can see them.');
}

const rows = [...found.values()];
rows.sort(function (a, b) { return b.used_in.length - a.used_in.length; });

return rows.slice(0, cap).map(function (r) {
  return { json: Object.assign({}, r, { used_in: [...new Set(r.used_in)] }) };
});

// runOnceForEachItem, so the registry answer stays paired with the package it
// was asked about - the HTTP node replaces the item's json wholesale.
//
// `time.modified` is not used and must not be. Measured 2026-08-31: `request`
// reports modified 2026-07-17 and its own latest version was published
// 2020-02-11. modified moves when anybody edits any metadata, including the
// deprecation notice, so a staleness check built on it calls every abandoned
// package healthy.
const src = $('Only The npm Ones').item.json;
const body = $json || {};

if (body.error || !body['dist-tags']) {
  return { json: Object.assign({}, src, {
    found: false,
    registry_note: 'npm had no answer for this name (' + String(body.error || 'no dist-tags') + ').',
  }) };
}

const latest = String((body['dist-tags'] || {}).latest || '');
const times = body.time || {};
const versionData = (body.versions || {})[latest] || {};

// The deprecation notice lives on the version object, not on the package root.
const deprecated = versionData.deprecated ? String(versionData.deprecated).slice(0, 240) : '';

return { json: Object.assign({}, src, {
  found: true,
  latest: latest,
  published: times[latest] || '',
  first_published: times.created || '',
  release_count: Object.keys(body.versions || {}).length,
  maintainers: (body.maintainers || []).length,
  license: String(versionData.license || body.license || ''),
  deprecated: deprecated,
  homepage: String(versionData.homepage || body.homepage || ''),
}) };

// Same pairing reason as the npm reader.
//
// `urls` is the file list for the version in `info`, so its upload time is the
// latest release date without pulling the whole `releases` map, which on a
// popular package is megabytes of JSON per request.
const src = $('Only The Python Ones').item.json;
const body = $json || {};
const info = body.info || {};

if (!info.version) {
  return { json: Object.assign({}, src, {
    found: false,
    registry_note: 'PyPI had no answer for this name.',
  }) };
}

const files = body.urls || [];
let published = files.length ? String(files[0].upload_time_iso_8601 || '') : '';
if (!published) {
  const rel = (body.releases || {})[info.version] || [];
  published = rel.length ? String(rel[0].upload_time_iso_8601 || '') : '';
}

// info.home_page is null on modern uploads; the repository link moved into
// project_urls under a name the publisher chose, so several are tried.
const urls = info.project_urls || {};
const homepage = String(
  info.home_page || urls.Source || urls.Homepage || urls.Repository || urls.Code || ''
);

return { json: Object.assign({}, src, {
  found: true,
  latest: String(info.version),
  published: published,
  first_published: '',
  release_count: Object.keys(body.releases || {}).length,
  maintainers: info.author || info.maintainer ? 1 : 0,
  license: String(info.license || '').slice(0, 60),
  // A yanked release is PyPI's deprecation: the maintainer pulled it.
  deprecated: info.yanked ? ('Yanked from PyPI: ' + String(info.yanked_reason || 'no reason given')) : '',
  homepage: homepage,
}) };

// OSV takes one package and one version. The version sent is always the bare
// number produced upstream, never the manifest's range - measured 2026-08-31,
// a range is not rejected, it is misread as the floor, and the answer comes
// back with advisories that were fixed before the range was written.
//
// A dependency with no usable version at all is asked about without one, which
// returns every advisory ever filed against the package. That is noise as a
// vulnerability list and a finding as a fact: nobody knows what version is
// installed.
const p = $json;

const query = { package: { name: p.name, ecosystem: p.osv_ecosystem } };
if (p.version) { query.version = p.version; }

return { json: Object.assign({}, p, { osv_body: query, version_known: !!p.version }) };

// The second half of the range fix. OSV was asked about a bare version, but the
// version it was asked about is often the floor of a range rather than what is
// installed, so every advisory is checked against its own `fixed` event here
// before it is allowed to count.
//
// An advisory whose affected range ends in `last_affected` rather than `fixed`
// has no fix at all. Measured on `request` 2.88.2, GHSA-p8p7-x288-28g6: bumping
// the version does nothing, the package has to go. That is the difference
// between an upgrade ticket and a migration ticket, and it is not on any
// dashboard.
const src = $('Ask The Right Question').item.json;
const body = $json || {};
const vulns = Array.isArray(body.vulns) ? body.vulns : [];

const RANK = { CRITICAL: 4, HIGH: 3, MODERATE: 2, MEDIUM: 2, LOW: 1 };

function compareVersions(a, b) {
  // Numeric compare on the release part only. A prerelease suffix is ignored,
  // which errs towards reporting: 2.0.0-rc1 is treated as 2.0.0.
  const pa = String(a).split(/[-+]/)[0].split('.');
  const pb = String(b).split(/[-+]/)[0].split('.');
  for (let i = 0; i < 3; i += 1) {
    const x = Number(pa[i] || 0);
    const y = Number(pb[i] || 0);
    if (x !== y) { return x < y ? -1 : 1; }
  }
  return 0;
}

function severityOf(v) {
  const ds = v.database_specific || {};
  const named = String(ds.severity || '').toUpperCase();
  if (RANK[named]) { return named; }
  // No named severity: read the CVSS base score out of the vector's own field.
  const cvss = (v.severity || []).find(function (s) { return String(s.type || '').indexOf('CVSS') === 0; });
  if (!cvss) { return 'UNKNOWN'; }
  const m = String(cvss.score || '').match(/\/C:([NLH])\/I:([NLH])\/A:([NLH])/);
  if (!m) { return 'UNKNOWN'; }
  const worst = ['N', 'L', 'H'].indexOf(m.slice(1).sort().pop());
  return worst >= 2 ? 'HIGH' : worst === 1 ? 'MODERATE' : 'LOW';
}

const kept = [];
let noFix = 0;
let worst = '';

for (const v of vulns) {
  const affected = (v.affected || []).filter(function (a) {
    return !a.package || String((a.package || {}).name || '').toLowerCase() === String(src.name).toLowerCase();
  });

  const fixes = [];
  let sawRange = false;
  for (const a of affected) {
    for (const r of a.ranges || []) {
      for (const e of r.events || []) {
        if (e.fixed) { fixes.push(String(e.fixed)); sawRange = true; }
        if (e.last_affected) { sawRange = true; }
      }
    }
  }

  // Already past the fix: the range floor was old, the advisory does not apply.
  if (src.version && fixes.length) {
    const stillOpen = fixes.some(function (f) { return compareVersions(src.version, f) < 0; });
    if (!stillOpen) { continue; }
  }

  const sev = severityOf(v);
  if (!fixes.length && sawRange) { noFix += 1; }
  if ((RANK[sev] || 0) > (RANK[worst] || 0)) { worst = sev; }

  kept.push({
    id: String(v.id || ''),
    cve: (v.aliases || []).filter(function (x) { return String(x).indexOf('CVE-') === 0; })[0] || '',
    severity: sev,
    summary: String(v.summary || v.details || '').replace(/\s+/g, ' ').slice(0, 180),
    fixed_in: fixes.sort(compareVersions)[0] || '',
    has_fix: fixes.length > 0,
  });
}

kept.sort(function (a, b) { return (RANK[b.severity] || 0) - (RANK[a.severity] || 0); });

return { json: Object.assign({}, src, {
  vuln_count: kept.length,
  worst_severity: worst || 'NONE',
  no_fix_count: noFix,
  advisories: kept.slice(0, 6),
  fix_to: kept.filter(function (a) { return a.has_fix; }).map(function (a) { return a.fixed_in; })[0] || '',
}) };

// Arithmetic, on purpose. Whether a package is deprecated, how long since its
// last release and how bad its worst open advisory is are all facts, and a
// language model asked to weigh facts it cannot check adds a bill and a way to
// be wrong about a number. The model gets called once, later, on the shortlist.
function compareVersions(a, b) {
  const pa = String(a).split(/[-+]/)[0].split('.');
  const pb = String(b).split(/[-+]/)[0].split('.');
  for (let i = 0; i < 3; i += 1) {
    const x = Number(pa[i] || 0);
    const y = Number(pb[i] || 0);
    if (x !== y) { return x < y ? -1 : 1; }
  }
  return 0;
}

const cfg = $('Settings').first().json;
const warnDays = Math.max(90, Number(cfg.stale_warn_days) || 365);
const deadDays = Math.max(warnDays + 1, Number(cfg.stale_dead_days) || 730);
const now = Date.now();

// The registry answers came through the merge, the advisories are the input.
const health = new Map();
for (const i of $('Both Registries').all()) {
  const r = i.json || {};
  if (r.package_key) { health.set(r.package_key, r); }
}

const out = [];

for (const item of $input.all()) {
  const a = item.json || {};
  const h = health.get(a.package_key) || a;

  const published = h.published ? Date.parse(h.published) : NaN;
  const staleDays = isFinite(published) ? Math.round((now - published) / 86400000) : null;

  const reasons = [];
  let risk = 0;

  if (h.deprecated) { risk += 40; reasons.push('the maintainers marked it deprecated'); }
  if (a.no_fix_count > 0) {
    risk += 35;
    reasons.push(a.no_fix_count + ' advisory with no fix released');
  }
  if (a.worst_severity === 'CRITICAL') { risk += 30; reasons.push('a critical advisory is open'); }
  else if (a.worst_severity === 'HIGH') { risk += 22; reasons.push('a high advisory is open'); }
  else if (a.worst_severity === 'MODERATE') { risk += 10; reasons.push('a moderate advisory is open'); }
  else if (a.worst_severity === 'LOW') { risk += 3; reasons.push('a low advisory is open'); }

  // Age on its own is not a finding. `escape-html` has not shipped in eleven
  // years because it is twenty lines that do one thing correctly, and a report
  // that lists it next to an open CVE is the noise this workflow exists to
  // remove. Staleness only counts when there is a second reason to look: you
  // are behind the latest version, or one person is holding it up.
  const behind = !!(h.latest && a.version && compareVersions(a.version, h.latest) < 0);
  const alone = h.found && h.maintainers <= 1;
  if (staleDays === null) { risk += 5; reasons.push('no release date could be read'); }
  else if (staleDays > deadDays && (behind || alone)) {
    risk += 25;
    reasons.push('no release in ' + Math.round(staleDays / 365) + ' years' + (behind ? ', and you are on ' + a.version + ' against ' + h.latest : ', held up by one maintainer'));
  } else if (staleDays > warnDays && behind) {
    risk += 10;
    reasons.push('no release in ' + Math.round(staleDays / 30) + ' months and you are behind ' + h.latest);
  }

  if (h.found && h.maintainers === 1) { risk += 5; reasons.push('one maintainer'); }
  if (!a.version_known) { risk += 8; reasons.push('the manifest does not say which version is installed'); }
  if (!a.pinned && a.vuln_count > 0) { reasons.push('the range allows ' + a.version + ' or newer, so a lockfile may already cover this'); }

  // A build-time dependency is a smaller blast radius than a runtime one.
  if (a.dev_only) { risk = Math.round(risk * 0.4); reasons.push('development dependency only'); }

  let verdict = 'fine';
  if (h.deprecated || (a.no_fix_count > 0 && ['CRITICAL', 'HIGH'].indexOf(a.worst_severity) >= 0)) {
    verdict = 'replace';
  } else if (a.vuln_count > 0) {
    verdict = 'upgrade';
  } else if (staleDays !== null && staleDays > deadDays && behind) {
    // Old and behind is a problem. Old and current is a finished package:
    // `escape-html` has not shipped in eleven years because twenty lines that
    // escape HTML correctly do not need shipping again, and a report that lists
    // it beside an open CVE is the noise this workflow exists to remove.
    verdict = 'watch';
  }

  out.push({ json: {
    package_key: a.package_key,
    name: a.name,
    ecosystem: a.ecosystem,
    version: a.version || 'unknown',
    pinned: !!a.pinned,
    latest: h.latest || '',
    published: h.published || '',
    stale_days: staleDays,
    deprecated: h.deprecated || '',
    maintainers: h.maintainers || 0,
    license: h.license || '',
    homepage: h.homepage || '',
    used_in: a.used_in || [],
    dev_only: !!a.dev_only,
    vuln_count: a.vuln_count || 0,
    worst_severity: a.worst_severity || 'NONE',
    no_fix_count: a.no_fix_count || 0,
    advisories: a.advisories || [],
    fix_to: a.fix_to || '',
    risk: risk,
    verdict: verdict,
    reasons: reasons,
  }});
}

return out;

// Everything the loop handed back, ranked. The model only ever sees this
// shortlist, so the bill does not grow with the size of the dependency tree.
const cfg = $('Settings').first().json;
const shortlist = Math.max(3, Math.min(30, Number(cfg.shortlist) || 15));

const rows = $input.all().map(function (i) { return i.json; }).filter(function (r) { return r && r.name; });
rows.sort(function (a, b) { return b.risk - a.risk; });

const worth = rows.filter(function (r) { return r.verdict !== 'fine'; });
const top = worth.slice(0, shortlist);

const lines = top.map(function (r) {
  const adv = (r.advisories || []).slice(0, 2).map(function (a) {
    return a.severity + ' ' + (a.cve || a.id) + (a.has_fix ? ' (fixed in ' + a.fixed_in + ')' : ' (no fix released)');
  }).join('; ');
  return [
    '- ' + r.ecosystem + ' ' + r.name + '@' + r.version,
    '  last release: ' + (r.published ? r.published.slice(0, 10) : 'unknown') + (r.stale_days === null ? '' : ' (' + r.stale_days + ' days ago)'),
    '  deprecated: ' + (r.deprecated ? r.deprecated.slice(0, 120) : 'no'),
    '  advisories: ' + (adv || 'none'),
    '  used in: ' + (r.used_in || []).join(', '),
  ].join('\n');
}).join('\n');

// A step that can return nothing ends the branch, and the quiet path below it
// would never fire. One marker item always comes back.
return [{ json: {
  has_findings: top.length > 0,
  scanned: rows.length,
  shortlist_count: top.length,
  replace_count: rows.filter(function (r) { return r.verdict === 'replace'; }).length,
  upgrade_count: rows.filter(function (r) { return r.verdict === 'upgrade'; }).length,
  watch_count: rows.filter(function (r) { return r.verdict === 'watch'; }).length,
  rows: rows,
  top: top,
  evidence: lines,
}}];

// The model is asked for JSON and usually returns it, sometimes inside a code
// fence and occasionally cut off mid-sentence when the shortlist runs long.
//
// A truncated answer is the interesting case. Parsing the whole string fails,
// so the naive version returns nothing and a run that found nine problems
// reports none. Complete objects are collected one at a time instead, at any
// depth, which turns a cut-off answer into a shorter list rather than an empty
// one - collecting only top-level objects fails on exactly this case, because
// the wrapper never closes.
//
// single-item input: one shortlist, one answer.
const found = $('Build The Shortlist').first().json;
const raw = String(($input.first().json || {}).text || '');

const ACTIONS = ['replace', 'upgrade', 'watch'];

function objectsIn(text) {
  const out = [];
  const starts = [];
  let inString = false;
  let escaped = false;
  for (let i = 0; i < text.length; i += 1) {
    const c = text[i];
    if (inString) {
      if (escaped) { escaped = false; }
      else if (c === '\\') { escaped = true; }
      else if (c === '"') { inString = false; }
      continue;
    }
    if (c === '"') { inString = true; continue; }
    if (c === '{') { starts.push(i); continue; }
    if (c === '}' && starts.length) {
      const s = starts.pop();
      try { out.push(JSON.parse(text.slice(s, i + 1))); } catch (e) { /* partial */ }
    }
  }
  return out;
}

const parsed = objectsIn(raw);
let items = [];
for (const o of parsed) {
  if (Array.isArray(o.items)) { items = o.items; break; }
}
if (!items.length) {
  items = parsed.filter(function (o) { return o && o.name && o.one_liner; });
}

const said = new Map();
for (const it of items) {
  const key = String((it.ecosystem || '') + '::' + (it.name || '')).toLowerCase();
  // The model ignores an enum often enough to plan for. Anything off the list
  // becomes the scored verdict rather than a new category nobody defined.
  let action = String(it.action || '').toLowerCase().trim();
  if (ACTIONS.indexOf(action) < 0) { action = ''; }
  if (it.name) { said.set(key, { action: action, one_liner: String(it.one_liner || '').slice(0, 240) }); }
}

return found.top.map(function (r) {
  const m = said.get((r.ecosystem + '::' + r.name).toLowerCase()) || {};
  return { json: Object.assign({}, r, {
    verdict: m.action || r.verdict,
    advice: m.one_liner || 'No note came back for this one; the scored reasons are below.',
    reported_on: new Date().toISOString().slice(0, 10),
    summary: r.name + '@' + r.version + ' - ' + (r.reasons || []).slice(0, 2).join(', '),
  }) };
});

// One message, whatever the size of the shortlist. Slack posts per item
// otherwise, and a dependency audit that arrives as fourteen notifications is
// a dependency audit nobody reads.
//
// single-item input: this runs executeOnce and reads the whole list by name.
const found = $('Build The Shortlist').first().json;
const rows = $('Read The Recommendations').all().map(function (i) { return i.json; });

const byVerdict = { replace: [], upgrade: [], watch: [] };
for (const r of rows) { (byVerdict[r.verdict] || byVerdict.watch).push(r); }

function line(r) {
  const sev = r.vuln_count ? ' _' + r.worst_severity.toLowerCase() + '_' : '';
  // The age below is the age of the package's own latest release, which reads
  // as reassuring next to a version you are four majors behind on. Where there
  // is a gap, the gap is the more useful number.
  const gap = r.latest && r.latest !== r.version ? ' - latest is ' + r.latest : '';
  const age = gap || (r.stale_days === null ? '' : ' - last release ' + Math.round(r.stale_days / 30) + ' months ago');
  return '- `' + r.name + '@' + r.version + '`' + sev + age + '\n   ' + r.advice;
}

const parts = ['*Dependency risk across ' + (found.scanned || 0) + ' packages*'];
if (byVerdict.replace.length) {
  parts.push('\n*' + byVerdict.replace.length + ' to replace*\n' + byVerdict.replace.map(line).join('\n'));
}
if (byVerdict.upgrade.length) {
  parts.push('\n*' + byVerdict.upgrade.length + ' to upgrade*\n' + byVerdict.upgrade.map(line).join('\n'));
}
if (byVerdict.watch.length) {
  parts.push('\n*' + byVerdict.watch.length + ' to watch*\n' + byVerdict.watch.slice(0, 8).map(line).join('\n'));
}

const loose = rows.filter(function (r) { return r.vuln_count > 0 && !r.pinned; });
if (loose.length) {
  parts.push('\n_' + loose.length + ' of these come from a version range, not a pin. If your lockfile sits higher than the floor, the advisory may already be covered._');
}

return [{ json: { message: parts.join('\n'), replace_count: byVerdict.replace.length } }];

// The issue body is built rather than mapped, because an issue that lists three
// packages is one ticket somebody closes and three tickets is three they do not.
//
// single-item input: one issue per run, holding every replace verdict.
const rows = $('Read The Recommendations').all()
  .map(function (i) { return i.json; })
  .filter(function (r) { return r.verdict === 'replace'; });

const body = rows.map(function (r) {
  const adv = (r.advisories || []).map(function (a) {
    return '  - ' + a.severity + ' [' + (a.cve || a.id) + '](https://osv.dev/vulnerability/' + a.id + ')'
      + (a.has_fix ? ' - fixed in ' + a.fixed_in : ' - **no fix released**');
  }).join('\n');
  return [
    '### `' + r.name + '@' + r.version + '` (' + r.ecosystem + ')',
    '',
    r.advice,
    '',
    '- last release: ' + (r.published ? r.published.slice(0, 10) : 'unknown'),
    '- ' + (r.deprecated ? 'deprecated: ' + r.deprecated : 'not deprecated'),
    '- used in: ' + (r.used_in || []).join(', '),
    adv || '  - no advisories, flagged on maintenance alone',
  ].join('\n');
}).join('\n\n');

return [{ json: {
  issue_title: 'Dependency risk: ' + rows.length + ' package' + (rows.length === 1 ? '' : 's') + ' to replace',
  issue_body: body + '\n\n---\nOpened automatically from the manifests in the repos listed in the workflow settings.',
}}];
